import{_ as t,H as a,f as o,i as s}from"./chunks/framework.Cvt1eIE0.js";const y=JSON.parse('{"title":"Philosophy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/philosophy.md","filePath":"en/guide/philosophy.md"}'),i={name:"guide/philosophy.md"};function n(r,e,l,p,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="philosophy" tabindex="-1">Philosophy <a class="header-anchor" href="#philosophy" aria-label="Permalink to &quot;Philosophy&quot;">​</a></h1><h2 id="intent-not-instruction" tabindex="-1">Intent, not instruction <a class="header-anchor" href="#intent-not-instruction" aria-label="Permalink to &quot;Intent, not instruction&quot;">​</a></h2><p>Tell the agent what to achieve and what done looks like. Let it decide how to do it.</p><p>Step-by-step recipes become obsolete as agents get smarter. Declarations of intent stay relevant — they encode <em>what matters</em>, not <em>how to get there</em>.</p><h2 id="pay-for-discipline-only-when-it-pays-back" tabindex="-1">Pay for discipline only when it pays back <a class="header-anchor" href="#pay-for-discipline-only-when-it-pays-back" aria-label="Permalink to &quot;Pay for discipline only when it pays back&quot;">​</a></h2><p>Triage decides. A typo fix doesn&#39;t need a spec. A new system does. Praxis applies overhead proportional to complexity.</p><table tabindex="0"><thead><tr><th>Task</th><th>Praxis cost</th></tr></thead><tbody><tr><td>Fix a typo</td><td>~450 tokens (bootstrap only)</td></tr><tr><td>Standard feature (design→ship)</td><td>~1,300 tokens</td></tr><tr><td>Complex task (all skills)</td><td>~2,900 tokens</td></tr></tbody></table><h2 id="skills-are-short" tabindex="-1">Skills are short <a class="header-anchor" href="#skills-are-short" aria-label="Permalink to &quot;Skills are short&quot;">​</a></h2><p>If a rule needs 3,000 tokens to express, it&#39;s probably not a rule — it&#39;s a manual. Praxis skills average ~230 tokens each.</p><p>Short skills mean agents read them fully, follow them reliably, and the framework stays maintainable as AI capabilities evolve.</p><h2 id="specs-are-facts-not-plans" tabindex="-1">Specs are facts, not plans <a class="header-anchor" href="#specs-are-facts-not-plans" aria-label="Permalink to &quot;Specs are facts, not plans&quot;">​</a></h2><p>A spec is a list of decisions: contracts, invariants, failure modes, test criteria. No narrative, no rationale, no step-by-step. Plans are separate, and they&#39;re milestone stubs — not scripts.</p><p>The agent brings domain knowledge. Praxis provides structure for what needs to be decided, not instructions for how to decide it.</p>',13)])])}const f=t(i,[["render",n]]);export{y as __pageData,f as default};
